const form = $("รับแจ้งปัญหา").first().json;
const ai = $input.first().json;

// แปลงผลลัพธ์จาก AI เป็น Object
function parseAI(value) {
  if (value && typeof value === "object" && !Array.isArray(value)) {
    return value;
  }

  if (typeof value !== "string" || !value.trim()) {
    return {};
  }

  const text = value.trim()
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  try {
    return JSON.parse(text);
  } catch (e) {
    const start = text.indexOf("{");
    const end = text.lastIndexOf("}");

    if (start !== -1 && end > start) {
      try {
        return JSON.parse(text.slice(start, end + 1));
      } catch (e2) {}
    }

    return { "ข้อความจาก AI": text };
  }
}

let raw = ai.output ?? ai.text ?? ai.response ?? ai;
let data = parseAI(raw);

if (typeof data.output === "string") {
  data = parseAI(data.output);
} else if (data.output && typeof data.output === "object") {
  data = data.output;
}

// เลือกค่าที่มีข้อมูล
function pick(...values) {
  for (const value of values) {
    if (
      value !== undefined &&
      value !== null &&
      String(value).trim() !== ""
    ) {
      return value;
    }
  }
  return "";
}

// ข้อมูลจากฟอร์ม
const ชื่อผู้แจ้ง = pick(form["ชื่อผู้แจ้ง"]);
const อีเมล = pick(form["อีเมล"]);

const อุปกรณ์ = pick(
  form["ประเภทอุปกรณ์"],
  form["อุปกรณ์"],
  data["อุปกรณ์"]
);

const หมายเลขเครื่อง = pick(
  form["หมายเลขอุปกรณ์"],
  form["หมายเลขเครื่อง"],
  data["หมายเลขเครื่อง"]
);

const สถานที่ = pick(
  form["ห้องเรียน"],
  form["สถานที่"],
  data["สถานที่"]
);

const อาการเสีย = pick(
  form["อาการ/ปัญหาที่พบ"],
  form["อาการเสีย"],
  data["อาการเสีย"]
);

// ผลวิเคราะห์จาก AI
const สาเหตุ = pick(
  data["สาเหตุ"],
  data["สาเหตุที่คาดว่าเกิดขึ้น"],
  data["สาเหตุที่เป็นไปได้"]
);

const ความเร่งด่วน = pick(
  data["ความเร่งด่วน"],
  data["ระดับความเร่งด่วน"],
  data["urgency"],
  data["priority"],
  ai["ความเร่งด่วน"],
  ai["ระดับความเร่งด่วน"]
);

const รายละเอียด = pick(
  data["แนวทางแก้ไขเบื้องต้น"],
  data["รายละเอียด"],
  data["แนวทางแก้ไข"],
  data["วิธีแก้ไข"],
  data["ข้อเสนอแนะ"],
  data["คำแนะนำ"],
  data["รายละเอียดการแก้ไข"]
);

// ตรวจสอบค่าการส่งต่อ
const ค่าส่งต่อ = String(
  pick(data["ต้องส่งต่อผู้รับผิดชอบ"], "")
).trim();

let ต้องส่งต่อ;

if (ค่าส่งต่อ === "ใช่" || ค่าส่งต่อ.toLowerCase() === "yes") {
  ต้องส่งต่อ = "ใช่";
} else if (
  ค่าส่งต่อ === "ไม่" ||
  ค่าส่งต่อ.toLowerCase() === "no"
) {
  ต้องส่งต่อ = "ไม่";
} else {
  ต้องส่งต่อ = "รอตรวจสอบ";
}

// กำหนดสถานะให้สอดคล้องกับผลการส่งต่อ
let สถานะ;

if (ต้องส่งต่อ === "ใช่") {
  สถานะ = "รอซ่อม";
} else if (ต้องส่งต่อ === "ไม่") {
  สถานะ = "รอแก้ไขเบื้องต้น";
} else {
  สถานะ = "รอตรวจสอบ";
}

// ยังไม่ถือว่าดำเนินการสำเร็จจนกว่าจะมีผลจริง
const ผลการดำเนินงาน = "รอดำเนินการ";

const ข้อความAI = pick(
  data["ข้อความจาก AI"],
  typeof raw === "string" ? raw : JSON.stringify(data)
);

// ตรวจสอบข้อมูลที่จำเป็น
const ข้อมูลที่ขาด = [];

if (!ชื่อผู้แจ้ง) ข้อมูลที่ขาด.push("ชื่อผู้แจ้ง");
if (!อีเมล) ข้อมูลที่ขาด.push("อีเมล");
if (!อุปกรณ์) ข้อมูลที่ขาด.push("อุปกรณ์");
if (!อาการเสีย) ข้อมูลที่ขาด.push("อาการเสีย");

if (!ความเร่งด่วน) {
  ข้อมูลที่ขาด.push("ความเร่งด่วน");
}

if (!รายละเอียด) {
  ข้อมูลที่ขาด.push("แนวทางแก้ไขเบื้องต้น");
}

if (ต้องส่งต่อ === "รอตรวจสอบ") {
  ข้อมูลที่ขาด.push("ผลการพิจารณาการส่งต่อผู้รับผิดชอบ");
}

const ผ่านการตรวจสอบ = ข้อมูลที่ขาด.length === 0;

// ส่งข้อมูลไปยัง Node ถัดไป
return [{
  json: {
    "ชื่อผู้แจ้ง": ชื่อผู้แจ้ง,
    "อีเมล": อีเมล,
    "อุปกรณ์": อุปกรณ์,
    "หมายเลขเครื่อง": หมายเลขเครื่อง,
    "สถานที่": สถานที่,
    "อาการเสีย": อาการเสีย,
    "สาเหตุ": สาเหตุ,
    "ความเร่งด่วน": ความเร่งด่วน,
    "รายละเอียด": รายละเอียด,
    "สถานะ": สถานะ,
    "ผลการดำเนินงาน": ผลการดำเนินงาน,
    "ต้องส่งต่อผู้รับผิดชอบ": ต้องส่งต่อ,
    "ข้อความจาก AI": ข้อความAI,
    "ข้อมูลครบถ้วน": ผ่านการตรวจสอบ,
    "ข้อมูลที่ขาด": ข้อมูลที่ขาด.join(", ")
  }
}];

const items = $input.all();

// แปลงค่าจาก Google Sheets ให้เป็นข้อความอย่างปลอดภัย
function getText(row, key) {
  const value = row[key];
  if (value === null || value === undefined || value === '') {
    return '-';
  }
  return String(value).trim();
}

// ป้องกันอักขระในข้อมูลทำให้ HTML ของอีเมลผิดรูปแบบ
function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// ทำให้ค่าที่ใช้จัดกลุ่มมีรูปแบบสม่ำเสมอ
function normalize(value) {
  return String(value ?? '')
    .trim()
    .replace(/\s+/g, ' ')
    .toLowerCase();
}

// ปรับชื่อสถานะที่อาจเขียนต่างกันให้เป็นกลุ่มเดียวกัน
function normalizeStatus(value) {
  const v = normalize(value);

  if (!v || v === '-') return 'ไม่ระบุสถานะ';
  if (v.includes('เสร็จ') || v.includes('ใช้งานได้ตามปกติ')) {
    return 'ซ่อมเสร็จแล้ว';
  }
  if (v.includes('กำลังซ่อม') || v.includes('กำลังดำเนินการ')) {
    return 'กำลังดำเนินการ';
  }
  if (v.includes('รอซ่อม')) return 'รอซ่อม';
  if (v.includes('รอตรวจสอบ')) return 'รอตรวจสอบ';
  if (v.includes('รอรับเรื่อง')) return 'รอรับเรื่อง';
  if (v.includes('ซ่อมไม่ได้') || v.includes('ไม่สามารถซ่อม')) {
    return 'ไม่สามารถซ่อมได้';
  }

  // คงสถานะต้นฉบับไว้ หากไม่ตรงกับกลุ่มข้างต้น
  return String(value).trim();
}

function normalizeUrgency(value) {
  const v = normalize(value);

  if (!v || v === '-') return 'ไม่ระบุ';
  if (v.includes('สูง')) return 'สูง';
  if (v.includes('ปานกลาง')) return 'ปานกลาง';
  if (v.includes('ต่ำ')) return 'ต่ำ';

  return String(value).trim();
}

const rows = items.map(item => item.json);

// นับรายการทั้งหมดที่ได้รับจาก Google Sheets
const total = rows.length;

// นับจำนวนตามสถานะ
const statusCounts = {};
for (const row of rows) {
  const status = normalizeStatus(row['สถานะ']);
  statusCounts[status] = (statusCounts[status] || 0) + 1;
}

// นับจำนวนตามระดับความเร่งด่วน
const urgencyCounts = {};
for (const row of rows) {
  const urgency = normalizeUrgency(row['ความเร่งด่วน']);
  urgencyCounts[urgency] = (urgencyCounts[urgency] || 0) + 1;
}

// สร้างแถวตารางรายละเอียดรายการแจ้งซ่อม
const detailRows = rows.map((row, index) => {
  const device = getText(row, 'อุปกรณ์');
  const number = getText(row, 'หมายเลขเครื่อง');
  const location = getText(row, 'สถานที่');
  const issue = getText(row, 'อาการเสีย');
  const urgency = normalizeUrgency(row['ความเร่งด่วน']);
  const status = normalizeStatus(row['สถานะ']);
  const reporter = getText(row, 'ชื่อผู้แจ้ง');
  const result = getText(row, 'ผลการดำเนินงาน');

  return `
    <tr>
      <td>${index + 1}</td>
      <td>${escapeHtml(device)}</td>
      <td>${escapeHtml(number)}</td>
      <td>${escapeHtml(location)}</td>
      <td>${escapeHtml(issue)}</td>
      <td>${escapeHtml(urgency)}</td>
      <td>${escapeHtml(status)}</td>
      <td>${escapeHtml(reporter)}</td>
      <td>${escapeHtml(result)}</td>
    </tr>`;
}).join('');

// สร้างตารางสรุป โดยเรียงตามชื่อกลุ่ม
function makeSummaryTable(data, heading) {
  const entries = Object.entries(data)
    .sort((a, b) => a[0].localeCompare(b[0], 'th'));

  const body = entries.length
    ? entries.map(([name, count]) => `
        <tr>
          <td>${escapeHtml(name)}</td>
          <td style="text-align:center">${count}</td>
        </tr>`).join('')
    : '<tr><td colspan="2">ไม่มีข้อมูล</td></tr>';

  return `
    <h3>${heading}</h3>
    <table>
      <thead><tr><th>รายการ</th><th>จำนวน</th></tr></thead>
      <tbody>${body}</tbody>
    </table>`;
}

const bangkokDate = new Intl.DateTimeFormat('th-TH', {
  dateStyle: 'long',
  timeZone: 'Asia/Bangkok'
}).format(new Date());

const html = `
<!DOCTYPE html>
<html lang="th">
<head>
<meta charset="UTF-8">
<style>
  body { font-family: Arial, Tahoma, sans-serif; color: #222; line-height: 1.5; }
  h2 { color: #174a7e; }
  h3 { color: #174a7e; margin-top: 24px; }
  table { border-collapse: collapse; width: 100%; margin: 12px 0 20px; }
  th, td { border: 1px solid #d6dce5; padding: 8px; text-align: left; vertical-align: top; }
  th { background: #edf3f8; }
  .total { background: #f2f6fa; padding: 14px; border-radius: 6px; }
  .note { color: #666; font-size: 12px; }
</style>
</head>
<body>
  <h2>รายงานสรุปการแจ้งปัญหาและติดตามการซ่อมอุปกรณ์</h2>
  <p>วันที่จัดทำรายงาน: ${escapeHtml(bangkokDate)}</p>
  <p class="note">
    รายงานนี้สรุปข้อมูลทั้งหมดที่มีอยู่ใน Google Sheets ณ เวลาที่สร้างรายงาน
  </p>

  <div class="total">
    <strong>จำนวนรายการแจ้งซ่อมทั้งหมด: ${total} รายการ</strong>
  </div>

  ${makeSummaryTable(statusCounts, 'สรุปจำนวนรายการตามสถานะ')}
  ${makeSummaryTable(urgencyCounts, 'สรุปจำนวนรายการตามความเร่งด่วน')}

  <h3>รายละเอียดรายการแจ้งซ่อม</h3>
  <table>
    <thead>
      <tr>
        <th>ลำดับ</th>
        <th>อุปกรณ์</th>
        <th>หมายเลขเครื่อง</th>
        <th>สถานที่</th>
        <th>อาการเสีย</th>
        <th>ความเร่งด่วน</th>
        <th>สถานะ</th>
        <th>ผู้แจ้ง</th>
        <th>ผลการดำเนินงาน</th>
      </tr>
    </thead>
    <tbody>
      ${detailRows || '<tr><td colspan="9">ยังไม่มีรายการแจ้งซ่อม</td></tr>'}
    </tbody>
  </table>

  <p>รายงานนี้สร้างและส่งโดยระบบอัตโนมัติผ่าน n8n</p>
</body>
</html>`;

return [{
  json: {
    subject: `รายงานสรุปการแจ้งซ่อมประจำสัปดาห์ - ${bangkokDate}`,
    total,
    statusCounts,
    urgencyCounts,
    html
  }
}];

const current = $('รับแจ้งปัญหา').first().json;
const oldRows = $input.all().map(item => item.json);

// ปรับข้อความให้อยู่ในรูปแบบที่เปรียบเทียบได้
function normalize(text) {
  return String(text ?? '')
    .toLowerCase()
    .replace(/\s+/g, '')
    .trim();
}

// จัดชื่ออุปกรณ์ที่เรียกต่างกันให้อยู่ในประเภทเดียวกัน
function deviceType(text) {
  const t = normalize(text);

  if (/แป้นพิมพ์|คีย์บอร์ด|keyboard/.test(t)) return 'keyboard';
  if (/เมาส์|เมาส์คอม|mouse/.test(t)) return 'mouse';
  if (/จอภาพ|จอมอนิเตอร์|monitor/.test(t)) return 'monitor';
  if (/คอมพิวเตอร์|คอมตั้งโต๊ะ|computer|pc/.test(t)) return 'computer';
  if (/เครื่องพิมพ์|printer/.test(t)) return 'printer';
  if (/โปรเจกเตอร์|projector/.test(t)) return 'projector';

  return t;
}

// จัดอาการที่มีความหมายใกล้เคียงกันเป็นกลุ่ม
function symptomType(text) {
  const t = normalize(text);

  if (/พิมพ์ไม่ติด|กดไม่ติด|กดแล้วไม่ขึ้น|พิมพ์ไม่ได้|ไม่มีตัวอักษร/.test(t)) {
    return 'keyboard_not_typing';
  }

  if (/คลิกไม่ติด|คลิกไม่ได้|กดเมาส์ไม่ได้/.test(t)) {
    return 'mouse_click_problem';
  }

  if (/เปิดไม่ติด|เปิดไม่ได้|เปิดไม่ขึ้น/.test(t)) {
    return 'cannot_turn_on';
  }

  if (/ภาพไม่ขึ้น|ไม่มีภาพ|จอไม่ติด/.test(t)) {
    return 'no_display';
  }

  return t;
}

const newDevice = deviceType(current['อุปกรณ์']);
const newNumber = normalize(current['หมายเลขเครื่อง']);
const newSymptom = symptomType(current['อาการเสีย']);

const openStatuses = [
  'รอแก้ไขเบื้องต้น',
  'รอดำเนินการ',
  'รอซ่อม',
  'กำลังดำเนินการ',
  'ไม่สามารถแก้ไขได้'
].map(normalize);

const duplicates = oldRows.filter(row => {
  // ข้ามแถวว่างที่อาจเกิดจาก Always Output Data
  if (!row['หมายเลขเครื่อง']) return false;

  const sameNumber =
    normalize(row['หมายเลขเครื่อง']) === newNumber;

  const sameDevice =
    deviceType(row['อุปกรณ์']) === newDevice;

  const sameSymptom =
    symptomType(row['อาการเสีย']) === newSymptom;

  const status = normalize(row['สถานะ']);
  const stillOpen = openStatuses.includes(status);

  return sameNumber && sameDevice && sameSymptom && stillOpen;
});

return [{
  json: {
    ...current,
    'พบรายการซ้ำ': duplicates.length > 0,
    'จำนวนรายการที่ตรงกัน': duplicates.length,
    'รายละเอียดรายการเดิม': duplicates.map(row => ({
      'หมายเลขเครื่อง': row['หมายเลขเครื่อง'],
      'อุปกรณ์': row['อุปกรณ์'],
      'อาการเสีย': row['อาการเสีย'],
      'สถานะ': row['สถานะ']
    }))
  }
}];
